import type { ToolGuide, GuideSection } from "./tool-guides";
export type FieldGuide = ToolGuide & { formula: string; example: string; audience: string; limitations: string };
const section=(id:string,title:string,...paragraphs:string[]):GuideSection=>({id,title,paragraphs});
const faq=(question:string,answer:string)=>({question,answer});
export const fieldGuides:Record<string,FieldGuide>={
  concrete: {
    title:"From measured concrete volume to a complete bid",audience:"For contractors planning the quantities and costs of a rectangular slab or uniform perimeter footing. Use measured dimensions and supplier quotes; the visual is a quantity sketch rather than a structural specification.",
    formula:"Solid slab: ft³ = length(ft) × width(ft) × depth(in) ÷ 12. yd³ = ft³ ÷ 27. Perimeter footing: area = outside rectangle − inside rectangle. Order = net volume × (1 + allowance/100). Bid = total entered cost ÷ (1 − margin/100).",
    example:"A 24 × 24 ft slab, 6 in deep, contains 288 ft³ or 10.6667 yd³. With 10% order allowance, purchase volume is 11.7333 yd³. At 0.60 ft³ per 80 lb bag, that is 528 whole bags. Without gravel or rebar costs, $165/yd³ concrete plus $1,000 prep/labor gives $2,936 cost and a $3,670 bid at 20% margin. These are hypothetical quantities and prices.",
    limitations:"No structural design, strength selection, soil evaluation or code approval. Footings are uniform perimeter rings without piers or intersections. Grid steel excludes laps, bends, supports and fabrication waste. Delivery minimums, tax and pump costs must be entered separately in other costs.",
    sections:[
      section("measure-concrete","Measure the pour before ordering",
        "Measure the actual planned concrete dimensions, not just a building's nominal size. Enter length and width in feet, then depth in inches. The tool converts the depth to feet before calculating volume. Confirm whether forms establish outside or inside dimensions and whether the bottom is level enough for a uniform-depth assumption. Small depth errors across a large slab can change the order materially.",
        "The slab sketch changes as the dimensions change, but its vertical depth is exaggerated so a thin layer remains visible on a screen. Read the numeric depth label instead of measuring the illustration. Irregular edges, steps, thickened sections and different elevations require separate quantity calculations. Do not force a complicated pour into one rectangle simply because its overall outside dimensions are easy to measure."),
      section("slab-footing","Understand the perimeter-footing model",
        "A solid slab fills its whole rectangular footprint. The footing mode instead removes an inside rectangle from the outside rectangle, using the same entered width around all four sides. That subtraction avoids counting the corners twice. The outside length and width remain feet, while the footing width and depth are entered in inches. The inside opening must remain positive for this model.",
        "For example, a 24 ft square outside footprint with a 1.5 ft wide perimeter has a 21 ft square inside opening. Its plan area is 576 minus 441, or 135 square feet. Multiplying by the footing depth gives its concrete volume. Crossings, pads, isolated piers and different footing widths are excluded. Calculate those separately rather than treating the ring result as a foundation design."),
      section("order-concrete","Separate measured volume from order allowance",
        "The net volume describes the entered geometry. The order quantity multiplies that volume by your allowance percentage. An allowance can reflect expected placement variation or purchasing practice, but the calculator does not prescribe a universal amount. Use the same measurement basis as the supplier and discuss the order, site access, discharge method and scheduling before committing to a delivery.",
        "The quantity is not silently rounded to a truck size. A ready-mix supplier may use delivery increments, minimum-load charges or other terms that require a different final order. Include those costs in the prep, labor and other-cost input. Pinning down which amount is measured and which amount is purchased also prevents a waste allowance from being added twice in another estimating worksheet."),
      { ...section("bagged-concrete","Compare bagged mix with ready-mix",
        "The bag alternative divides the order volume in cubic feet by the selected product yield, then rounds up to whole bags. The starting yields are specific to QUIKRETE Concrete Mix: an 80 lb bag is approximately 0.60 cubic feet and a 60 lb bag approximately 0.45 cubic feet. Bag weight alone is not enough to establish the yield of a different product.",
        "Changing the supply selection also changes the concrete cost unit: ready-mix uses dollars per cubic yard, while bagged mix uses dollars per bag. Enter the actual quoted price for that selection. The pallet or truck illustration is symbolic; it does not assign a delivery capacity or guarantee that hand mixing is practical for the size of your pour. Verify mixing, handling and placement requirements separately."),source:{label:"QUIKRETE Concrete Mix: published bag yields",href:"https://www.quikrete.com/pdfs/data_sheet-concrete%20mix%201101.pdf"}},
      section("grid-gravel","Use gravel and rebar as quantity assumptions",
        "The gravel toggle adds a uniform layer beneath the same modeled concrete footprint. Its order volume uses the gravel depth and the order allowance, with a separate gravel unit price. This is a purchase estimate, not a compaction specification. Confirm whether the quoted gravel quantity is loose or placed and whether delivery, compaction labor or extra excavation belongs in the other-cost allowance.",
        "For a slab, the grid estimates bars in two directions using the entered spacing and edge clearance. It includes both ends and distributes the bars so the modeled gap does not exceed the chosen spacing. The #4 or #5 selector changes the visual line weight; update the price for your chosen steel yourself. Counts and linear feet exclude laps and bends, and must not be interpreted as an engineered reinforcement schedule."),
      section("concrete-bid","Turn the takeoff into a reviewable quote",
        "Material cost includes concrete and the enabled gravel and grid-steel allowances. Add preparation, labor, equipment, overhead and other costs that you expect to bear. The bid divides that combined cost by one minus the margin as a decimal. A 20% margin uses a denominator of 0.80. Adding 20% as a markup would produce a different, lower margin on the same costs.",
        "Copy the summary to keep the quantity assumptions with the price. Prepare an estimate line to pass the bid to the document studio, then choose Add takeoff line there. That second step preserves an existing document until you decide to add the new work. Before sharing a quote, review scope, exclusions, delivery assumptions, tax treatment and payment timing against the actual job."),
    ],faqs:[faq("How many cubic yards are in a 24 × 24 × 6 in slab?","The net volume is 10.6667 cubic yards: 24 × 24 × 0.5 feet divided by 27. With a hypothetical 10% order allowance it becomes 11.7333 cubic yards. Supplier increments and site conditions may change the final order."),faq("Does the rebar overlay tell me what reinforcement to install?","No. It visualizes entered quantity assumptions. It does not select a code-compliant bar size, spacing, cover, lap length or support arrangement. Use the project's approved specifications and calculate additional fabrication needs separately."),faq("Are gravel and concrete both included in the bid?","Concrete is included using the selected supply unit. Gravel and slab-grid steel are included only when enabled, using their separate prices. Enter every other cost you need to recover in the prep, labor and other-cost allowance; avoid counting the same cost twice.")],
  },
  roofing:{
    title:"Measure roof area, then order by product coverage",audience:"For a simple rectangular gable or equal-pitch hip roof. This tool connects a plan measurement and pitch to purchase quantities; it does not replace a field takeoff for a complex roof.",
    formula:"Roof area = (length + 2 × overhang/12) × (width + 2 × overhang/12) × √(1 + (pitch/12)²). Squares = roof area ÷ 100. Bundles = round up(order area ÷ 100 × bundles per square).",
    example:"A hypothetical 40 × 24 ft building with 12 in overhang on every side has a 42 × 26 ft roof plan. At 6/12 pitch its sloped area is about 1,220.89 ft². With 10% allowance and three bundles per square, the purchase estimate is 41 bundles. At 400 ft² usable coverage per roll, it needs four underlayment rolls. Bundle and roll yields depend on the selected products.",
    limitations:"Uniform pitch and rectangular plan only. Valleys, dormers, penetrations, roof-edge detailing, ventilation, ridge caps and structural requirements are excluded. Enter accessory and underlayment costs separately. The illustration is a schematic, not a roof survey.",
    sections:[
      section("roof-plan","Start with the horizontal roof footprint",
        "Enter the building's length and width, then the overhang on each side in inches. The calculator adds twice the overhang to both dimensions, creating a horizontal roof footprint. This is different from measuring the sloped surface itself. If your measurements already include the full roof edges, set overhang to zero rather than adding it to a footprint that already contains it.",
        "A roof with different overhangs on different sides cannot be represented exactly by one uniform overhang field. Calculate an appropriate full footprint outside this tool or break the job into sections. Confirm the basis of each measurement before comparing two estimates: a building footprint, eave-to-eave plan and measured roof surface are three different quantities that can produce different answers."),
      section("roof-pitch","Read pitch as rise over twelve inches of run",
        "A 6/12 pitch means six inches of vertical rise for twelve inches of horizontal run. The pitch slider changes the illustrated height and the calculated slope multiplier together. The angle is the arctangent of rise divided by twelve. A 0/12 entry produces a flat mathematical area, but that result does not establish whether a shingle product or roof system is suitable for that slope.",
        "The slope factor multiplies the horizontal plan area by the square root of one plus the pitch ratio squared. At 6/12, the ratio is 0.5 and the multiplier is approximately 1.118. A steeper pitch increases sloped area for the same horizontal footprint. It can also affect labor and access costs, which must be entered separately rather than assumed to follow the same area multiplier."),
      section("roof-shape","Use the simple gable and hip assumptions correctly",
        "The gable view has two roof planes meeting at a ridge. The hip view uses four planes with the same pitch over a rectangular plan. For this simple equal-pitch model, the area factor is the same even though the edge layout differs. The hip mode requires length to be at least width so the modeled ridge can run along the longer dimension without a negative length.",
        "Complex hips, unequal pitches, valleys, dormers and intersecting additions need their own measurements. This tool does not infer those features from the shape selector. Neither view selects framing members or details roof loading. Treat the wireframe as a way to understand the stated measurement assumptions, then use actual roof sections and product requirements for a complete material list."),
      section("roof-squares","Convert area into squares and whole bundles",
        "A roofing square is a unit of area equal to 100 square feet. It is not one package of shingles. The calculator first reports net squares from the sloped area, then applies the order allowance and your entered bundles-per-square yield. Three bundles per square is an example starting value; the actual package coverage varies by product and must be checked before ordering.",
        "Bundle purchases round upward after the area and allowance are combined. Do not round the net squares upward first and then multiply by bundles, which can overstate the purchase count unnecessarily. Conversely, do not assume that an area-only quantity covers the layout waste from cuts, hips or valleys. The allowance is editable because waste depends on the selected material and actual roof geometry."),
      section("underlayment","Estimate usable underlayment coverage and accessories",
        "Enter the usable coverage of one roll after the overlap and installation requirements for your product. The starting 400 square feet is a hypothetical input, not a universal roll size. The purchase count divides the roof's allowance-adjusted area by that net coverage and rounds up. It does not add starter, ice-barrier zones or other extra layers that have a different coverage basis.",
        "Underlayment, flashing and other accessory costs belong in their separate dollar allowance. Include delivery and other material charges when applicable, and avoid counting costs already included in a bundle quote. Ridge caps, starter strips, fasteners, edge materials and ventilation components are not automatically quantified by this roof-area model. Keep a separate product checklist with the estimate so an apparently complete bundle count does not hide missing accessories."),
      section("roof-bid","Price the installation and review what is excluded",
        "The material total is whole bundles multiplied by your bundle price plus the accessory allowance. The prep, labor and other-cost input should account for the work you are quoting, such as tear-off, disposal, equipment, protection, cleanup and overhead. Changing pitch updates area and bundles immediately, but it does not automatically estimate the additional crew time or access equipment required for a steep roof.",
        "Choose a target margin only after the complete cost estimate is entered. Copy the bid summary or transfer it to the estimate studio to document the scope. Compare the result with your actual completed jobs and local supplier quotes. A quantity calculation is useful evidence for pricing, but it does not establish a market rate, customer acceptance or the suitability of a roofing system."),
    ],faqs:[faq("Is a roofing square the same as a square foot?","No. One roofing square is 100 square feet of roof area. A 1,200 square foot roof is twelve net squares before any order allowance. Bundle quantities then depend on the product's coverage."),faq("Why do gable and simple hip roofs show the same area?","For the same rectangular footprint and a uniform pitch on every plane, the slope multiplier applies to the whole plan. Edge lengths and cutting requirements differ. This model does not treat that equal area as equal labor or equal accessory demand."),faq("Does the calculator include shingles for valleys and ridges?","It estimates field-shingle bundles using your allowance. It does not separately quantify ridge caps, starter, valley materials or penetration details. Include those in a separate product takeoff and the accessory-cost allowance.")],
  },
  framing:{
    title:"Count a straight wall's studs without losing the end pieces",audience:"For rough quantity planning of a straight wall without openings. The elevation shows regular spacing, plate layers and corner allowances; it does not size structural members or provide an approved framing detail.",
    formula:"Regular studs = round up(wall length × 12 ÷ spacing in inches) + 1. Extra allowance = entered corners × 2 studs. Purchase studs = round up((regular + extra) × allowance factor). Cut length = overall height − 4.5/12 ft.",
    example:"A hypothetical 24 ft wall at 16 in on center has nineteen regular studs including both ends. Two entered corners add four allowance studs. Applying 10% purchase allowance gives 26 studs. An overall eight-foot wall with three 1.5-inch plates gives a 7.625 ft stud cut length. Three plate runs with 10% allowance require 79.2 linear feet of plate lumber.",
    limitations:"No openings, headers, king/jack studs, bracing, connectors, loads or code design. Two extra studs per corner is an editable-count convention, not a prescribed corner detail. Lumber stock must fit the cut length. Plate linear feet are not a optimized cutting or splice schedule.",
    sections:[
      section("wall-measure","Measure the complete wall run and overall height",
        "Enter the full length of the straight wall run in feet. Use the overall framed height, including the top and bottom plates, for the height field. The calculator assumes one bottom plate and two top plates, each 1.5 inches thick, then subtracts that combined plate thickness to report the stud cut length. It does not treat an eight-foot overall wall as requiring an eight-foot cut stud.",
        "Check how the project specifies wall height and whether pre-cut studs are being used. A stock length describes the purchased board, while a cut length describes the member after trimming. The tool flags stock that is shorter than the computed cut length. It does not recommend a wall height, member thickness or lumber grade; those come from the approved plans and applicable specifications."),
      section("stud-spacing","Count spacing intervals and both ends",
        "Convert the wall length to inches, divide by the entered on-center spacing, round the interval count upward and add one stud for the second end. The final interval may be shorter than the nominal spacing. For a twenty-four-foot run at sixteen inches on center, 288 divided by sixteen gives eighteen intervals, so the run has nineteen regular stud positions rather than eighteen.",
        "The elevation shows those positions across the entered length. On very long walls, the drawing simplifies repeated pieces so the page stays responsive; the numeric count remains the quantity estimate. On-center spacing is measured between stud centers, not between their clear faces. The visual stud width is exaggerated for readability and should not be used to measure an actual cavity or connection detail."),
      section("corners-backing","Keep corner and backing allowances explicit",
        "The entered corner count adds two extra studs per corner to the regular straight-run count. This is a transparent quantity allowance, not a universal corner assembly. Real corners, intersecting walls and backing requirements can use different arrangements. Set the count to reflect the additional members you intend to allow, then compare it with the actual plan instead of assuming the illustration resolves the connection.",
        "Do not automatically add a full end assembly a second time if the regular run already includes its end stud. The purpose of the extra allowance is to show the additional quantity separately. The diagram highlights the ends symbolically; it does not physically locate every corner you entered on one straight wall. Keep multiple walls and their intersections in a separate takeoff when they require different details."),
      section("stud-waste","Apply purchase allowance after the base count",
        "The purchase count applies your allowance to regular and extra studs together, then rounds up to whole purchased pieces. The starting ten percent is hypothetical. Review the material grade, expected defects, cutting pattern and your ordering practice before selecting a percentage. A higher allowance may cover more expected loss, but it does not fix a missing opening assembly or an incorrectly measured wall.",
        "The stock-length input checks that one purchased stud can supply one cut stud. The calculator does not optimize several short members from a longer board or automatically price different stock sizes. When you change the chosen stock length, update the cost per purchased stud to match the supplier's quote. Keep offcut reuse and any additional blocking quantities in your own material schedule."),
      section("wall-plates","Estimate the three plate runs separately",
        "One bottom run and two top runs total three times the wall length before the allowance. The calculator reports that length in feet and prices it using the entered cost per linear foot. For a twenty-four-foot wall, the base plate length is seventy-two feet; a ten percent allowance increases the purchase equivalent to 79.2 feet. That number is a length budget rather than a list of boards to order.",
        "Board lengths, splice locations, overlaps, intersections and cut reuse affect the actual purchase list. A plate-lumber supplier quote per board should be converted consistently to the linear-foot price or priced in a separate estimate. The tool does not lay out top-plate laps or establish fastening requirements. Include fasteners, connectors, treatments and other materials in your other-cost input when they belong to the quoted scope."),
      section("framing-bid","Add labor and compare with actual wall production",
        "Material cost combines the purchased stud count with the plate-lumber length allowance. Add layout, cutting, assembly, installation, equipment, overhead and other expected costs in the separate allowance. The bid then divides the combined cost by one minus the target margin. A visually full wall does not mean the estimate contains every expense needed to deliver it on site.",
        "Use the job cost tracker to compare planned and actual lumber and crew cost after the work. Record why a run needed extra backing, a different stock size or more time than expected. These observations can improve the next estimate more than silently increasing a general waste percentage. Transfer the finished bid to the estimate studio and describe the excluded openings and structural details clearly before sharing it."),
    ],faqs:[faq("Why is one added to the spacing count?","The intervals between studs are not the same as the number of studs. A straight run needs a member at both ends. Eighteen full intervals therefore have nineteen regular stud positions."),faq("Does this calculate window or door framing?","No. Openings require separate headers, king and jack studs, cripples, supports and details from the actual plans. This tool estimates an uninterrupted straight wall and explicit corner allowances."),faq("Can I use the elevation as a construction drawing?","No. It is a quantity illustration. Member dimensions, grade, spacing, bracing, connections and structural requirements must be taken from the approved project specifications.")],
  },
  drywall:{
    title:"Plan drywall sheets, seams and finish allowances together",audience:"For a single rectangular wall or ceiling surface. The staggered drawing helps explain joints and cuts, while the sheet purchase count remains an area-based estimate with your allowance rather than a cutting optimizer.",
    formula:"Net area = length × surface height/width − opening deductions. Sheets = round up(net area × allowance factor ÷ sheet area). Tape = modeled gross-layout interior seams × allowance factor. Compound buckets = round up(net area × allowance factor ÷ entered bucket coverage).",
    example:"A hypothetical 24 × 8 ft surface has 192 ft². With 4 × 8 ft sheets and 10% allowance, the area-based purchase count is seven sheets. The staggered two-row gross layout has 44 ft of interior seams, or 48.4 ft with allowance. At an assumed 400 ft² per compound bucket, it needs one bucket. Cuts, openings and the finish specification can change the actual purchase list.",
    limitations:"One rectangular surface. The sketch does not draw opening deductions, returns or structural backing. Sheet purchases use net area; tape uses gross-layout seams. No guaranteed compound yield, screw count, cut optimization or installation specification.",
    sections:[
      section("drywall-surface","Measure a wall or ceiling as one surface",
        "Enter the measured length and the second surface dimension in feet. For a wall, that second dimension is its height. For a ceiling, it is the plan width. Both cases use rectangular area, but the surface selector changes the label on the drawing so the estimate's basis is visible. Measure additional walls or ceiling sections separately if they have different dimensions or finishing requirements.",
        "The input represents one surface, not a whole room. A room may need four wall areas plus a ceiling, and some surfaces can use different board products. Keep those quantities separate where useful. The tool does not infer all room faces from one length and height, so a visually complete rectangle should not be interpreted as an automatically complete drywall package."),
      section("drywall-openings","Understand deductions and cut requirements",
        "Opening area subtracts from the gross surface to produce net area for the sheet and compound estimates. The deduction must remain smaller than the full surface. Enter an area in square feet, rather than a count of doors or windows. An opening does not always save the full purchase equivalent of its area because the surrounding board still needs to be cut, supported and installed.",
        "The drawing intentionally shows the gross surface; it does not pretend to locate openings from one total-area input. Small deductions may leave the rounded purchase count unchanged. Large deductions can reduce the area-based count without producing a usable cutting pattern. Review the actual openings and cut pieces before ordering, and treat the waste allowance as a purchasing assumption rather than proof that every offcut can be reused."),
      section("drywall-layout","Read the staggered sheet layout",
        "Choose four-by-eight or four-by-twelve-foot sheets. The sketch places the long dimension horizontally and uses four-foot-high rows. Alternate rows begin with a half-sheet offset to show staggered vertical joints. The last pieces at an edge may be shorter than a whole sheet. The labels indicate the drawn piece dimensions, not a guarantee that each piece needs a new purchased sheet.",
        "Staggering can create additional cut pieces even where net area suggests an exact sheet count. Reusing offcuts, changing orientation or choosing another sheet length can alter purchases and joint lengths. This tool does not solve that optimization or specify the manufacturer's installation pattern. Use the visual to inspect the stated assumptions, then review board orientation, backing and actual material requirements for the project."),
      section("drywall-tape","Estimate the modeled interior joint tape",
        "Tape length adds the horizontal seams between rows and the vertical seams inside each row. It excludes the rectangle's outside perimeter. The alternate offset means vertical seams can differ by row, so simply multiplying the number of sheets by a fixed perimeter would not represent this layout correctly. The reported value then applies the same entered order allowance.",
        "The tape model uses the gross rectangular layout, while the sheet count can use a net opening deduction. That distinction is shown in the output label. Inside corners, opening returns, perimeter details, bead and other finish accessories are not automatically included. If the quoted scope includes them, add their measured quantities and costs separately rather than assuming the tape number covers every junction."),
      section("drywall-compound","Set compound coverage from the actual finish",
        "The compound estimate divides allowance-adjusted net area by your coverage-per-bucket assumption and rounds up. The starting four hundred square feet is hypothetical; it is not a product promise or a universal finishing rate. Bucket size, joint type, application method, number of coats and finish level can change the required amount. Use the selected product's information and your actual job records to set the input.",
        "The bucket icons are symbolic and capped visually on large jobs so the page remains responsive. Read the numeric bucket count for the purchase estimate. Materials for a skim coat or another finish scope may need a different coverage assumption or separate line. An area-based compound estimate cannot automatically detect the finishing specification from sheet size or a wall-versus-ceiling selection."),
      section("drywall-price","Price sheets and finish materials without missing labor",
        "Material cost includes whole purchased sheets and compound buckets at the entered prices. Add tape, screws, bead, delivery and other materials to the prep, labor and other-cost allowance if they belong to your scope. Include handling, hanging, finishing, sanding, protection, cleanup and overhead there as well. The quantity model does not silently add a labor rate or assume an installed price per square foot.",
        "Review the proposed bid after all expected costs are entered and apply the target margin consistently. Copy the summary so the sheet size, surface dimensions, deduction and allowance remain attached to the estimate. Transfer it to the document studio when you are ready to describe the work. Compare the purchase estimate with actual sheets and compound used after completion to improve your next set of assumptions."),
    ],faqs:[faq("Why does the sheet count differ from the drawn pieces?","Purchase sheets are estimated from net area plus allowance. The drawing shows gross-layout pieces, including edge cuts and staggered rows. Offcut reuse and openings can change the actual cutting plan, so the drawing is not an optimized purchase schedule."),faq("Does the tape estimate include room corners?","No. It covers the interior seams in the modeled rectangle, with your allowance. Perimeter edges, inside corners, opening returns and bead require their own measured allowance where applicable."),faq("How much mud does one bucket cover?","There is no universal yield built into this tool. Enter a coverage assumption for the selected compound, bucket size and finish specification. The default is hypothetical and should be checked against product information and completed jobs.")],
  },
  room:{
    title:"Measure room area and translate it into the material you buy",audience:"For measured rectangles, an L-shaped footprint or a simple non-crossing polygon. Use the plan to understand area and perimeter, then choose flooring, tile or wall paint using your own material coverage.",
    formula:"Rectangle area = length × width. L-shape area = outside rectangle − rectangular cutout. Polygon area = absolute shoelace sum ÷ 2. Flooring = area × allowance factor. Tiles = round up(order area ÷ tile area). Paint = round up(net wall area × coats × allowance factor ÷ coverage).",
    example:"A hypothetical 20 × 16 ft room has 320 ft² and a 72 ft perimeter. Removing an 8 × 6 ft corner leaves 272 ft². Ten percent allowance gives 352 ft² of flooring for the full rectangle. At $4/ft² plus $1,000 labor/other costs, the rectangle's bid is $3,010 with a 20% target margin. These prices are illustrative, not a flooring price survey.",
    limitations:"Flat plan measurements only. No curved edges, slopes, holes, stock-cut optimization or automatic code sizing. Paint conversion covers walls, not ceilings; tile boxes depend on entered package contents. Polygon vertices must not cross or repeat adjacent points.",
    sections:[
      section("room-shape","Choose a shape that matches the measured footprint",
        "A rectangle uses two outside dimensions. The L-shape subtracts a rectangular corner cutout from that outside rectangle. Enter the cutout length and width in the same units as the outside dimensions, and keep each smaller than its corresponding outside dimension. The subtraction produces a visible notch instead of assuming that every irregular room can be represented accurately by one overall rectangle.",
        "Measure finished boundaries consistently and record whether built-in elements belong in your material scope. If a room has several notches, diagonal boundaries or another straight-edged plan, use the polygon mode. Curved boundaries and holes are not modeled. A measured room area is different from a purchase quantity: the order allowance is applied afterward and does not change the displayed geometric footprint."),
      section("polygon-room","Edit a simple polygon with handles or coordinates",
        "Polygon mode starts with six ordered vertices describing an L-shaped example. Drag the orange handles to move a point, or use the numbered X and Y coordinate inputs for a keyboard-accessible alternative. Coordinates are measured in feet from the canvas origin and are bounded to the visible forty-foot editing space. Keep the points in perimeter order so the outline follows the room boundary.",
        "The engine checks that the shape has positive area, distinct adjacent vertices and no crossing nonadjacent edges. An invalid outline produces an error instead of a confident purchase estimate. The shoelace formula calculates area from the ordered coordinates, while edge distances give perimeter. The tool does not survey the room or infer dimensions from a photo; the accuracy of the outline still depends on your measured input."),
      section("area-perimeter","Keep floor area and perimeter separate",
        "Area is measured in square feet and describes the floor footprint. Perimeter is measured in linear feet and describes the boundary around that footprint. These values serve different material calculations: flooring starts with area, while wall-paint area starts with perimeter multiplied by wall height. Do not substitute one for the other simply because both appear as measurements on the plan.",
        "Removing a corner rectangle from an outside rectangle reduces floor area but can leave perimeter unchanged because the removed outside edges are replaced by equal-length inside edges. More complex polygon changes can alter both. Watch the displayed results while editing the shape and check that the outline reflects the actual room. The dimensions on the schematic are edge lengths, not independent purchase quantities."),
      section("flooring-conversion","Convert floor area into flooring purchases",
        "Flooring mode multiplies the geometric floor area by the entered order allowance and reports purchase area in square feet. The starting ten percent is an example, not a prescribed waste amount. Layout direction, material width, pattern matching, cuts and damaged pieces can affect the actual purchase need. A simple area allowance cannot optimize a plank or roll cutting plan for the room.",
        "The material unit price in this mode is dollars per square foot of purchased flooring. If a supplier sells by a carton covering a fixed area, convert its quoted price consistently or round the final purchase to whole cartons separately. Add underlayment, trim, preparation and other scope costs in the labor and other-cost allowance. Do not assume the floor-area result contains those accessories automatically."),
      section("tile-conversion","Translate area into tiles and boxes",
        "Tile mode uses the entered length and width of one tile in inches, converts that tile area to square feet, and divides the allowance-adjusted floor area by it. The individual tile count rounds up before dividing by the entered tiles per box. The box count then rounds up again because a partial box may not be purchasable. Verify that your supplier's package contains the stated number of tiles.",
        "The material unit price changes to dollars per box in this mode. It does not remain a price per square foot. Nominal tile dimensions, grout spacing, patterned layouts, cuts and reserved spares can affect the practical purchase plan. This is an area conversion rather than a tile-set drawing. Include mortar, grout, preparation, trim and other required costs separately when pricing the installed scope."),
      section("paint-conversion","Calculate wall paint with height, openings and coats",
        "Paint mode multiplies the room perimeter by wall height, subtracts the entered wall-opening area, then applies coats and the order allowance. Dividing by your product's coverage per gallon per coat gives the purchase estimate, rounded up to whole gallons. The starting coverage is hypothetical. Surface condition, porosity, application and product requirements can change coverage; enter an assumption that reflects the work you plan to perform.",
        "The calculation covers walls only. It does not add the floor footprint as ceiling-paint area or automatically allow for doors, trim, primer or another product. The price unit changes to dollars per gallon. Add preparation, protection, application labor, cleanup and other costs before selecting the bid margin. Review the converted quantities and copy the summary so the material mode and assumptions remain visible alongside the price."),
    ],faqs:[faq("Can I calculate an L-shaped room without splitting it into two rooms?","Yes. Enter the outside rectangle and the rectangular corner cutout. The tool subtracts the cutout area and draws the resulting outline. For several irregular boundaries, use the polygon mode with measured vertices."),faq("Does paint mode include the ceiling?","No. It calculates wall area from perimeter and wall height, less your wall-opening deduction. Calculate a ceiling or a separate paint product as another scope rather than assuming it is included."),faq("Is the polygon canvas a measurement tool for a photo?","No. It visualizes coordinates that you supply. Use measured dimensions, keep vertices in boundary order and correct any crossing edges. The diagram does not derive site dimensions from imagery.")],
  },
  aggregate:{
    title:"Convert material volume to weight using the right density",audience:"For rectangular placed layers or an idealized conical stockpile. The visual connects dimensions, order volume and U.S. short tons using an explicit density, loose-volume factor and allowance.",
    formula:"Rectangular ft³ = length × width × depth(in)/12. Cone ft³ = π × radius² × height/3. yd³ = ft³/27. Order yd³ = net yd³ × loose-to-placed factor × allowance factor. U.S. short tons = order yd³ × 27 × density(lb/ft³)/2,000.",
    example:"A hypothetical 24 × 12 ft layer at four inches deep contains 96 ft³, or 3.5556 yd³. With factor 1.0 and 10% allowance, order volume is 3.9111 yd³. Using the illustrative density 105 lb/ft³ gives 5.544 U.S. short tons. At $45 per ton plus $1,000 labor/other costs, a 20% margin produces a $1,561.85 bid. Verify density and delivery pricing with the supplier.",
    limitations:"Illustrative editable bulk densities, not guaranteed material weights. No survey of an irregular pile, soil-bearing evaluation or compaction design. U.S. short tons differ from metric tonnes. Supplier minimums and delivery charges are not automatic.",
    sections:[
      section("aggregate-volume","Measure the volume you are trying to fill",
        "For a pad or trench, enter length and width in feet and placed layer depth in inches. The tool converts depth to feet, multiplies the three dimensions and divides by twenty-seven to report cubic yards. Measure the actual fill space rather than a nominal project size. Variations in existing grade, excavation or layer depth may require several sections instead of one uniform rectangular model.",
        "The rectangular diagram exaggerates depth so a shallow layer can be seen clearly. Read the numeric measurement and volume labels rather than scaling the picture. A trench with changing width or a pad on uneven ground is not automatically represented by its widest or deepest dimension. Break variable sections into separate estimates and combine them using a consistent loose-versus-placed basis."),
      section("cone-stockpile","Use a cone only for a roughly conical pile",
        "The conical-pile option uses radius and vertical height in feet. Radius is half the base diameter; entering the full diameter as radius would make the estimated volume four times larger because radius is squared. The formula divides the circular-base area times height by three. It assumes a complete circular base and a single peak, not an irregular stockpile bounded by walls or terrain.",
        "An actual pile may have a flattened top, a noncircular footprint or an uneven base. The cone result is a geometric estimate and should not be treated as a surveyed quantity. Measure representative dimensions carefully and compare the assumptions with the actual pile. Changing a density selector changes weight, while changing radius or height changes both volume and weight."),
      section("bulk-density","Choose a condition-specific bulk density",
        "Bulk density is weight per unit of occupied material volume, including the spaces between particles. The material selector provides illustrative starting values for gravel, crushed stone, topsoil and mulch, but each remains editable. Moisture, particle grading, source and compaction can change the actual value. Ask the supplier for a density that matches the material and condition used in your order.",
        "The calculation multiplies order cubic yards by twenty-seven cubic feet per yard and by pounds per cubic foot. It then divides pounds by two thousand to show U.S. short tons. This is not a metric-tonne conversion. If a supplier quotes another weight unit, convert it consistently before comparing totals. A familiar material name by itself does not guarantee a precise tonnage."),
      section("loose-placed","Separate loose volume from placed volume",
        "The loose-to-placed factor converts your measured geometric volume to an order-volume basis. A factor of one means no conversion. A higher factor increases the volume being ordered for the same placed space. The tool does not supply a universal compaction factor because the relationship depends on the material, condition and placement process. Obtain an appropriate factor from the supplier or project specifications.",
        "Keep that conversion separate from the order allowance. The conversion addresses the volume basis; the allowance addresses additional purchasing need you choose to model. Adding both without understanding what a supplier's quote already includes can double-count an allowance. Note the basis with your estimate so another person can tell whether a cubic-yard figure represents loose delivered material, measured placed space or an already adjusted purchase quantity."),
      section("aggregate-order","Read order volume and tonnage together",
        "The tool reports net measured volume, adjusted order volume and estimated order weight. These are related, but they are not interchangeable quantities. A supplier selling by weight needs the density-based tonnage; a supplier selling by loose volume needs the corresponding cubic yards. Select the pricing unit to match the quote and enter the price in that unit instead of applying a per-ton price to a cubic-yard quantity.",
        "Delivered load size, minimum order, truck access, unloading conditions and delivery fees can change the purchase cost without changing the fill geometry. The tool does not silently round to a truck capacity or assume a particular vehicle. Review those terms separately. A volume-to-weight conversion can help compare quotes, but only when the unit definitions and material condition are consistent."),
      section("aggregate-bid","Build the placed-material bid and learn from delivery",
        "Material cost uses the selected order quantity multiplied by your matching supplier unit price. Add delivery, equipment, excavation, handling, placement, compaction labor, overhead and other expected costs in the separate allowance. The target margin then applies to the combined entered cost. A material pile visualization does not automatically account for the work or conditions needed to place that material successfully.",
        "Copy the summary to preserve the density, loose-volume factor and order allowance with the bid. Transfer it to the estimate studio to describe the installed scope and exclusions. After delivery and placement, compare the supplier's quantity records and actual costs with your estimate. Repeated differences may indicate a measurement or density assumption that needs adjustment, rather than a reason to add an unexplained percentage to every future job."),
    ],faqs:[faq("How many tons are in one cubic yard of gravel?","There is no single guaranteed number. At an illustrative 105 lb/ft³, one cubic yard weighs 27 × 105 ÷ 2,000 = 1.4175 U.S. short tons. Use the supplier's density for the actual material condition."),faq("Is a U.S. short ton the same as a metric tonne?","No. This calculator uses 2,000 pounds per U.S. short ton. A metric tonne is a different unit. Match the supplier's pricing and delivery units before comparing an estimated weight with a quote."),faq("Does the allowance automatically cover compaction?","No. Loose-to-placed conversion and order allowance are separate inputs. Use a suitable conversion factor for the material, then apply any additional allowance deliberately. The default factor of one assumes no volume conversion.")],
  },
  benchmark:{
    title:"Use cost per square foot as a scenario, not a substitute for scope",audience:"For comparing your own installed-cost assumptions across a measured area. Starting ranges are hypothetical examples from the project brief, not verified regional price benchmarks or promises of an attainable market price.",
    formula:"Selected rate = low + (high − low) × slider position/100. Planning total = area × selected rate. Material/labor/other shares divide that same total. Premium scenario = area × high × premium factor.",
    example:"For a hypothetical 400 ft² slab, a $6–$14/ft² range has a $10 arithmetic midpoint. The midpoint planning total is $4,000. At 45% material and 40% labor allocation, those portions are $1,800 and $1,600, with $600 remaining for other/overhead. A 1.2 premium factor on the high assumption gives $6,720. These are user-defined planning figures, not surveyed regional costs.",
    limitations:"No live local pricing, regional adjustments, material specification or scope takeoff. Shares allocate the existing total; they do not add costs. The midpoint is arithmetic rather than a market average. A label naming a region does not validate the entered range.",
    sections:[
      section("cost-scope","Define exactly what your unit-cost range includes",
        "A cost-per-square-foot figure is meaningful only with a defined scope. A garage slab can mean a concrete pour alone or a larger installed package that includes excavation, base, reinforcement and finishing. A room addition can include very different work depending on structure, finishes and services. A roof replacement may include tear-off and disposal or only new installation. Write down the scope before comparing unit rates.",
        "The planner provides example ranges for those three scope names, but the values are not presented as collected market data. Choosing a scope changes the starting range; it does not fill in a specification or verify a regional price. Replace both ends with your actual quotes or documented assumptions and record what those numbers include. Otherwise, a polished spectrum can give a precise-looking total for an undefined job."),
      section("cost-area","Match the area basis to the price basis",
        "Enter the area to which the chosen installed rate applies. For a slab, that may be its footprint. For a roof, it may be sloped roof area rather than the building's floor area. For an addition, the agreed measurement basis may differ from another contractor's quote. Do not multiply a roof-surface unit price by floor area simply because both are expressed in square feet.",
        "Use the visual takeoff tools to calculate the relevant geometric area where their assumptions fit the project. Keep net measured area separate from material purchase area with waste. The planner's installed-cost rate may already include a material allowance, so multiplying it by an inflated purchase area could apply the same allowance twice. Compare the definitions alongside the final total, not only the displayed dollars."),
      section("cost-spectrum","Read low, midpoint, high and premium correctly",
        "The slider interpolates between your low and high assumptions. At zero percent it selects low; at one hundred percent it selects high. At fifty percent it selects their arithmetic midpoint. The interface deliberately labels that point as a midpoint instead of an average because the calculator has no set of local observations from which to compute a market average or typical project cost.",
        "The premium scenario multiplies your high assumption by an editable factor and then by area. It is a separate sensitivity comparison rather than another point on the low-to-high slider. A factor of 1.2 means twenty percent above the entered high rate. It does not represent a researched premium-finish price or a guarantee that a client will accept the resulting amount."),
      section("cost-region","Use local evidence rather than automatic region labels",
        "The region or quote-label field is a note that can be included in the copied summary. Typing a city or state does not secretly apply a multiplier or make the range current for that location. Build the range from comparable supplier quotes, subcontractor bids or completed jobs, and note when those figures were gathered. A location name cannot correct an outdated or mismatched cost basis.",
        "When comparing jobs, review size, access, specification, schedule and inclusions. A small project can have a higher installed unit cost because mobilization and fixed tasks are spread over fewer square feet. Large projects can have other constraints. Those effects belong in your assumptions or a detailed estimate; the planner does not invent regional or scale factors from the area input."),
      section("cost-breakdown","Allocate the total without adding it again",
        "Material share and labor share are percentages of the selected planning total. The remaining percentage becomes other and overhead allocation. Material and labor shares together cannot exceed one hundred percent. These amounts partition the same total; they are not additional charges layered on top of area multiplied by unit cost. That distinction keeps the spectrum and cost breakdown mathematically consistent.",
        "The shares are also user-defined. A forty-five percent material allocation is an example, not a researched cost ratio for every slab, roof or addition. Use your own cost records to decide whether the split is useful. If the installed rate includes contractor profit, some of the other allocation may represent that profit; this planner does not identify it automatically or calculate a separate job margin from the shares."),
      section("cost-next-step","Move from a scenario to a detailed bid",
        "Use the planner to discuss a range and test how area or scope assumptions change a total. Before issuing a bid, build the material, labor, equipment and overhead estimate that supports it. The takeoff tools connect measured quantities with entered costs and a target margin; the financial calculators help review profitability and collection timing. Those checks give the broad unit-cost scenario an actual business basis.",
        "Copy the summary or prepare an estimate line when you want to preserve a planning figure in a document. Label it as a scenario or allowance where appropriate rather than presenting an unsupported range as a fixed contracted price. Review scope, exclusions and payment terms with the actual project information. A more detailed estimate can then replace the preliminary figure without hiding why the price changed."),
    ],faqs:[faq("Are these verified prices for my city?","No. The initial ranges are hypothetical examples. Enter ranges supported by your own local quotes or completed jobs. A region label is a note and does not trigger a regional price adjustment."),faq("Why is the center labeled midpoint instead of average?","It is the arithmetic halfway point between the two numbers you entered. The tool does not have a sample of local project prices from which to calculate an observed average."),faq("Does the material breakdown add to the displayed total?","No. Material, labor and other shares divide the existing planning total. They are not added again. Use a detailed takeoff and cost estimate when you need to establish an actual bid margin.")],
  },
  estimate:{
    title:"Create a clear estimate or invoice without an account",audience:"For contractors preparing a customer document in their browser. The studio stores one local draft, calculates itemized totals and provides a clean print layout; it does not send invoices, process payments or collect signatures.",
    formula:"Line amount = quantity × rate, rounded to cents. Subtotal = line amounts. Discount = subtotal × discount%. Tax = discounted taxable lines × tax%. Retainage = discounted pre-tax subtotal × retainage%. Current due = total after tax − retainage.",
    example:"Suppose concrete is 12 yd³ × $165 = $1,980 and site preparation is $1,000. Subtotal is $2,980. A 10% discount leaves $2,682. If only concrete is taxable at 8%, tax is $142.56 after the proportional discount. Five percent retainage is $134.10. Total is $2,824.56 and proposed current payment is $2,690.46. Tax and retainage treatment are assumptions to verify for the job.",
    limitations:"USD document arithmetic only. No accounting ledger, payment processing, tax-jurisdiction determination or electronic signatures. Tax applies to marked discounted lines; retainage applies before tax. Long documents may print on multiple pages. Local storage is not a cloud backup.",
    sections:[
      section("document-purpose","Choose an estimate or an invoice deliberately",
        "An estimate describes proposed work and its price assumptions. An invoice requests payment for the work or billing event you identify. Choose the document type before entering the number, date and due or valid-until date. The studio changes the visible labels, but it does not decide whether work was accepted, completed or billable under the agreement. Those facts come from your project records.",
        "Use a meaningful document number so the saved file and customer copy can be connected with the job. Enter the contractor and client details as you want them printed, including relevant contact or address information. A project label helps distinguish work for a customer with several sites. The document remains a local draft until you print or export it and share it through your own process."),
      section("document-items","Describe line items with a consistent quantity and unit",
        "Each item has a description, quantity, unit and unit price. The line amount multiplies quantity by price and rounds to cents. A line for twelve cubic yards at a price per cubic yard is different from one complete installed job at a fixed quoted amount. Make the unit visible so a client can understand the basis instead of treating every quantity as an unexplained multiplier.",
        "Descriptions can include the scope or a concise reference to supporting documents, but a price table should not hide exclusions or schedule conditions. The studio supports up to thirty lines and does not silently delete rows from the printed copy. Add separate items where it makes the work easier to understand. Review quantities and rates after importing a takeoff, because that transferred line contains a full modeled bid rather than an automatic material-only charge."),
      section("document-transfer","Add a takeoff bid without replacing the draft",
        "A visual tool's Prepare estimate line action creates a local session transfer. When you open the studio, it shows the pending description and price with an Add takeoff line button. Nothing is added to an existing document until you choose that button. A completely blank starting line can be replaced by the transfer; otherwise the new item is appended so the current document remains visible.",
        "The transferred quantity is one job and the rate is the takeoff's modeled bid. It is not a second set of material quantities to add on top of the same installed scope. Review the description, tax status, unit and price before using it. Dismiss a transfer if it is no longer relevant. The transfer is local to this browser session and is not sent through a URL or a server."),
      section("discount-tax","Apply discounts and tax to the intended basis",
        "The discount percentage applies to the whole subtotal and is distributed proportionally when calculating the taxable portion. Mark each line that should be taxable under your actual treatment. The tax rate then applies only to those discounted taxable amounts. The tool does not infer taxability from a line description, your address or the state where the project is located.",
        "Review the resulting tax treatment for the transaction rather than assuming that the example matches local requirements. Rounding is performed at the displayed line and total stages so the document's dollar amounts reconcile. A discount changes the amount charged; it does not reduce the underlying job cost. Check the financial effect separately if you want to know whether the revised selling price still meets your margin goal."),
      section("retainage-terms","Keep retained money separate from a price reduction",
        "Retainage is calculated on the discounted pre-tax subtotal in this studio. It reduces the proposed current payment or current amount due, while remaining part of the total contract or invoice amount. This basis is stated beside the inputs because agreements and tax treatment can differ. A five percent retainage is not the same as giving the client another five percent discount.",
        "Write the agreed payment schedule, acceptance conditions and release terms in the terms area. Add scope exclusions and other relevant notes separately. The studio does not decide when retainage is collectible or whether a client has accepted an estimate. Its signature line is a space for a process outside the tool, not an electronic-signature service. Check cash timing separately if retained amounts affect your ability to fund the work."),
      section("print-backup","Print a customer copy and keep a recoverable backup",
        "Print / Save PDF opens the browser's print dialog. Choose a printer or Save as PDF and review the preview before sharing the document. The print stylesheet removes the site's navigation, footer and editing controls. Short documents are arranged to fit a page, while longer descriptions, terms or item lists continue onto additional pages rather than clipping important rows or shrinking them into unreadable text.",
        "The JSON backup preserves editable fields; a printed PDF preserves the customer-facing document. Download both when you need an archive. Restoring a backup requires an explicit replacement choice so a selected file does not silently overwrite the current draft. Local storage belongs to this browser and domain and can be removed by clearing site data. It is convenient working storage, not a substitute for saved records you control."),
    ],faqs:[faq("Is an email address or account required?","No. The studio works without an account or email capture. Document fields remain in local browser storage and are not sent to a server by this tool."),faq("Does retainage reduce the total invoice?","It reduces current due, not the total amount. The studio calculates it on the discounted pre-tax subtotal. Confirm that this basis matches the actual agreement and transaction treatment."),faq("Can every document print on exactly one page?","Short documents are designed for a compact page. Longer descriptions, terms or item lists can need more pages. The layout preserves all rows instead of hiding content to force a one-page output.")],
  },
  waiver:{
    title:"Prepare lien documents with the state and payment facts visible",audience:"For preparing a reviewable lien-document draft using verified official form language for California, Texas or Florida. The General option is not a universal legal form. Generation does not sign, deliver, serve, file or verify payment.",
    formula:"Select the project jurisdiction, document type and payment stage. Enter the exact project and payment facts. Conditional and unconditional forms have different effects; the tool does not calculate or decide legal rights from the amount entered.",
    example:"A hypothetical California progress-payment draft identifies the claimant, customer, owner, job location, through date, check maker, payee and check amount. Its conditional form states that effectiveness depends on receipt of payment. Switching to an unconditional form changes the statutory notice and payment statement; it is not merely a new title on the same document. Review the actual transaction before printing.",
    limitations:"No legal determination, electronic signature, payment verification or notice-service calculation. Official sources can change. General drafts require local review and may be unsuitable where statutory forms are required. Florida Notice to Owner generation does not establish timely or proper service.",
    sections:[
      section("waiver-jurisdiction","Start with the project's jurisdiction and the right source",
        "Select the state where the project and relevant legal requirements apply. California, Texas and Florida have separate form language in this tool, with official source links beside the editor. A familiar document title does not mean another state's wording is interchangeable. Check the current source, project type, claimant's role and transaction before deciding that the selected draft is appropriate.",
        "The General option is intentionally marked as a review draft rather than a universal state-compliant waiver. Some jurisdictions require specific forms or restrict the rights and timing of a release. A general draft can help gather information for review, but its availability does not establish validity. Do not switch to General merely to bypass a state-specific form requirement or an unresolved question about the project's governing rules."),
      { ...section("conditional-payment","Distinguish conditional release from actual paid status",
        "A conditional form connects its effectiveness to the identified payment condition. An unconditional form states that the relevant payment has been received and can have consequences even when the signer misunderstands the payment status. In California, CSLB publishes different conditional and unconditional forms for progress and final payment, including prominent notices that the tool keeps in the printed document.",
        "For an unconditional draft, the editor asks you to confirm actual receipt of cleared funds before enabling its print action. That confirmation is your statement, not bank verification by the website. A promised transfer, issued check or future payment schedule is different from cleared payment. The tool never signs the form and does not replace the evidence or review needed for the real transaction."),source:{label:"California CSLB: conditional and unconditional release forms",href:"https://cslb.ca.gov/consumers/Legal_Issues_For_Consumers/Mechanics_Lien/Conditional_And_Unconditional_Waiver_Release_Form.aspx"}},
      section("progress-final","Choose progress or final payment and preserve exceptions",
        "Progress and final forms do not necessarily release the same scope. Review the through date, furnished work, reserved items and payment stage carefully. California progress forms preserve stated categories of exceptions, while final forms use their own disputed-extras field. The editor provides those fields instead of replacing all forms with one generic paragraph. Enter explicit zero amounts where the actual reserved amount is zero.",
        "A date should identify the applicable work or document event, not be chosen solely because it is today's date. Review whether executed changes, retainage, disputed extras or unpaid earlier progress payments affect the draft. Blank exception fields should not be treated as a completed review. The tool inserts the supplied facts into the selected language, but cannot know whether a statement about payment or work is true."),
      { ...section("texas-release","Review Texas attachments and payment statements",
        "Texas forms are prepared from Property Code section 53.284. The progress forms refer to attached statements or progress payment requests and include statements concerning payment of the signer's laborers, subcontractors, materialmen and suppliers. Those references remain in the generated draft. The website does not create the supporting attachments or verify that the represented downstream payments have occurred.",
        "Attach the actual supporting statements where the selected form calls for them and review the quoted scope against those records. The printed unconditional notice remains bold and at least as large as the other form type. A clean PDF cannot make an inaccurate payment statement true. Confirm the applicable source and transaction before signing or relying on the document rather than treating the print action as a legal-compliance certificate."),source:{label:"Texas Legislature: Property Code §53.284",href:"https://statutes.capitol.texas.gov/?code=PR&tab=1&chapter=PR.53&artSec=53.284"}},
      { ...section("florida-notice","Keep a Florida release separate from a Notice to Owner",
        "Florida release drafts use the progress and final language in section 713.20. The conditional check option adds an identified check-payment condition under subsection seven and labels it as such. Florida's Notice to Owner is a separate document based on section 713.06, with its own warning, identifying information and recipients. A waiver and a notice should not be substituted for each other because they appear in the same tool.",
        "The Florida notice editor collects owner and claimant addresses, furnished-work information and copies recipients. It does not determine every required recipient, calculate a service deadline or serve the notice. Review the current statute and applicable service requirements for the actual facts. In other states, the notice option is only ordinary payment correspondence, clearly labeled as nonstatutory; it is not presented as a preliminary notice or a lien filing."),source:{label:"Florida Legislature: Chapter 713, including §§713.20 and 713.06",href:"https://www.leg.state.fl.us/statutes/index.cfm?App_mode=Display_Statute&URL=0700-0799/0713/0713.html"}},
      section("waiver-review","Review the full preview and preserve the final records",
        "Required identifying fields and the review acknowledgment must be complete before printing. Read the entire live preview, including the warning, scope, exceptions and signature area. The draft marker disappears only when the editor's completeness checks are satisfied; that is not an independent determination of legal validity. Signature lines remain blank for execution through a separate, appropriate process.",
        "Save a JSON backup of the editable draft and a PDF of the customer-facing copy when needed. Restoring a backup requires confirmation of replacement and clears the review acknowledgments so the restored facts are checked again. Local storage is browser-specific and is not an archive of delivery, signatures, payment evidence or service. Keep the real transaction records with the finalized document outside this tool."),
    ],faqs:[faq("Is the General template valid in every state?","No. It is a clearly labeled review draft, not a universal state-approved waiver. Review the applicable jurisdiction's requirements before using it; a required statutory form may make a general draft unsuitable."),faq("Does printing an unconditional waiver prove I was paid?","No. The editor requires your cleared-payment acknowledgment, but it cannot verify bank records. The statutory notice and payment statement must be reviewed before signing or relying on the actual document."),faq("Does generating a Florida Notice to Owner serve it?","No. The tool prepares a draft only. It does not identify all recipients, calculate deadlines, deliver, serve or file the notice. Review the actual notice and service requirements separately.")],
  },
};
